#tp .tp-main{flex:1;min-width:0;display:flex;flex-direction:column;overflow:hidden}
#tp .tp-side{width:170px;flex-shrink:0;display:flex;flex-direction:column;border-left:1px solid var(--border)}
#tp .tp-resizer{width:5px;flex-shrink:0;cursor:col-resize;position:relative;background:transparent}
#tp .tp-resizer::after{content:'';position:absolute;top:0;bottom:0;left:2px;width:1px;background:var(--border);transition:background .2s}
#tp .tp-resizer:hover::after,#tp .tp-resizer.dragging::after{background:var(--cyan)}
#tp.iv-expanded .tp-resizer{display:none}
#tp .tp-side-blank{flex:1;overflow-y:auto;padding:0;scrollbar-width:thin;scrollbar-color:var(--border) transparent;display:flex;flex-direction:column}
