#txti{flex:1;background:transparent;border:none;outline:none;color:var(--cyan);font-family:var(--mono);font-size:12px;letter-spacing:1px;caret-color:var(--cyan);resize:none;overflow-y:auto;max-height:160px;line-height:1.5;padding:6px 0;margin:0;display:block}
